const BIRTH_NEIGHBOUR_COUNT = 3;

function isAlive(cell: Cell, livingCells: Cell[]): boolean {
  return livingCells.some((living) => isSameCell(cell, living));
}

function candidates(livingCells: Cell[]): Cell[] {
  const found: Cell[] = [];
  for (const [x, y] of livingCells) {
    for (let dx = -1; dx <= 1; dx++) {
      for (let dy = -1; dy <= 1; dy++) {
        const candidate: Cell = [x + dx, y + dy];
        if (!isAlive(candidate, found)) found.push(candidate);
      }
    }
  }
  return found;
}

export function nextGeneration(livingCells: Cell[]): Cell[] {
  return candidates(livingCells).filter((cell) =>
    isAlive(cell, livingCells)
      ? survives(cell, livingCells)
      : countLivingNeighbours(cell, livingCells) === BIRTH_NEIGHBOUR_COUNT,
  );
}

