import { describe, it, expect } from "vitest";
import { nextGeneration, type Cell } from "./game-of-life.js";

function reference(cells: Cell[]): Cell[] {
  const alive = new Set(cells.map(([x, y]) => `${x},${y}`));
  const count = (x: number, y: number) => {
    let n = 0;
    for (let dx = -1; dx <= 1; dx++)
      for (let dy = -1; dy <= 1; dy++) {
        if (!dx && !dy) continue;
        if (alive.has(`${x + dx},${y + dy}`)) n++;
      }
    return n;
  };
  const cand = new Set<string>();
  for (const [x, y] of cells)
    for (let dx = -1; dx <= 1; dx++)
      for (let dy = -1; dy <= 1; dy++) cand.add(`${x + dx},${y + dy}`);
  const out: Cell[] = [];
  for (const k of cand) {
    const [x, y] = k.split(",").map(Number) as [number, number];
    const n = count(x, y);
    if (alive.has(k) ? n === 2 || n === 3 : n === 3) out.push([x, y]);
  }
  return out;
}

const key = (cs: Cell[]) => cs.map((c) => c.join(",")).sort().join(" | ");

describe("fuzz against reference", () => {
  it("matches on 500 random sparse boards incl. negatives", () => {
    let seed = 12345;
    const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
    for (let t = 0; t < 500; t++) {
      const n = Math.floor(rnd() * 10);
      const cells: Cell[] = [];
      for (let i = 0; i < n; i++)
        cells.push([Math.floor(rnd() * 11) - 5, Math.floor(rnd() * 11) - 5]);
      const uniq = [...new Map(cells.map((c) => [c.join(","), c])).values()];
      expect(key(nextGeneration(uniq))).toBe(key(reference(uniq)));
    }
  });
});
EOF
